func loadZones(path string, out *Zones) error {
	f, err := rt.ReadDataFile(path, ZonesSchema)
	if err != nil {
		return err
	}
	if f.Rows == nil {
		return rt.Missing(path, "", "rows")
	}
	var rows []json.RawMessage
	if err := jsonRead(path, "", "rows", f.Rows, &rows); err != nil {
		return err
	}
	values := make([]Zone, len(rows))
	keys := make([]ZoneID, len(rows))
	for i, raw := range rows {
		id, retired, err := jsonRowID(path, fmt.Sprintf("rows[%d].", i), raw)
		if err != nil {
			return err
		}
		if err := decodeZone(path, fmt.Sprintf("rows[%d].", i), raw, &values[i]); err != nil {
			return err
		}
		values[i].id, values[i].retired = ZoneID(id), retired
		keys[i] = values[i].id
	}
	if at, first, ok := rt.FirstDup(keys); ok {
		return rt.DupRow(path, fmt.Sprintf("rows[%d].", at), "$id", rt.WireToken(string(keys[at])), fmt.Sprintf("rows[%d]", first))
	}
	out.rows = rt.MakeKeyedList(values, keys)
	return nil
}

